import{z as o,x as B,o as n,c as d,q as E,j as i,D as e,d as t,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"摆动曲线","description":"","frontmatter":{"title":"摆动曲线","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/swing-curve.md","filePath":"litho/swing-curve.md","lastUpdated":1791413859000}'),A={name:"litho/swing-curve.md"};function p(D,a,h,C,m,_){const r=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=E('<h1 id="摆动曲线" tabindex="-1">摆动曲线 <a class="header-anchor" href="#摆动曲线" aria-label="Permalink to &quot;摆动曲线&quot;">​</a></h1><div class="epigraph"><p>胶厚变四分之一光学波长，耦合进胶的能量和驻波相位一起走；CD 跟着振荡。剂量环锁不住这条横轴。</p><footer>—— Mack 对 swing curve 的讨论；薄膜周期见 Born &amp; Wolf</footer></div><p><a href="/litho/thin-film-reflectivity">上一课</a>给出了复反射 \\(r\\)。缺口是：产线看见的不是一张 \\(r\\) 表，而是 <strong>CD（或 \\(E_\\mathrm{size}\\)）随胶厚振荡</strong>——摆动曲线（swing curve）。主干驻波课已经警告过；本课把振荡的周期、振幅与剂量闭环的分工钉死。胶厚怎么选，留给<a href="/litho/resist-thickness-selection">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>胶厚 \\(d\\) 变，两件事同时发生：进入胶的净耦合（顶面与底面多次反射的能量）变；驻波相位变，有效产酸沿 \\(z\\) 的积分变。阈值模型下，要维持同一 CD 所需剂量振荡，固定剂量下 CD 振荡。周期在胶内约为 \\(\\lambda/(2n)\\) 量级（正入射；大角度略改）。振幅由顶面反射与底面 \\(|r|\\) 共同决定。</p><p><span class="marginnote">「摆动曲线」就是拿胶厚当横轴、CD 当纵轴扫出来的一条波浪线：厚度每变约半个光波波长，CD 就上下摆一个来回，故名「摆动」。它不是机器坏了，是薄膜干涉在厚度轴上的体现。</span></p><p>缺口不是再推 Fresnel 矩阵，而是：摆动的横轴是厚度，纵轴是 CD / 剂量，剂量计闭环锁的是面能量，不锁 \\(d\\)。涂覆不均、台阶上的局部厚薄，走的就是这条横轴。把 CD 摆动写成「灯漂了」，会去拧剂量而留下 BARC 事故。</p><h3 id="顶与底两头" tabindex="-1">顶与底两头 <a class="header-anchor" href="#顶与底两头" aria-label="Permalink to &quot;顶与底两头&quot;">​</a></h3><p>底面 \\(|r|\\) 大 → 驻波深，摆动振幅大，BARC 主要压这一头。顶面胶–空气（或水、或 TARC）反射大 → 多次反射的能量摆动，即使底面已暗，仍可有较小的 swing。后课 TARC 管顶头，不要在本课把两头合成「一个反射率」。</p><p><span class="marginnote">浸没改顶面介质，摆动振幅和相位都会变；BARC 仍按胶下 \\(r\\) 选。换水不自动换 BARC 厚度最优解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：同一掩模、同一剂量焦点，扫胶厚，量 CD，得 swing。模拟：用上一课的栈算 \\(I(z;d)\\)，进产酸 / 阈值，切 CD\\((d)\\)。极大极小对应驻波相位与耦合的极值。减反良好时振幅压到工艺窗以内；减反失败时一个纳米级厚度误差就能把 CD 打出规格——EPE 预算里光学行必须声明是否含这条。</p><p>高 NA：不同 \\(\\theta\\) 的周期略不同，摆动被角谱糊一截，振幅可能下降，但角平均 \\(r\\) 仍可很大。不要把「高 NA 摆动自然消失」写成定理。</p>',13)),(n(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%83%B6%E5%8E%9A%20d%22%5D%20--%3E%20COUP%5B%22%E5%87%80%E8%80%A6%E5%90%88%E8%83%BD%E9%87%8F%22%5D%0A%20%20D%20--%3E%20PHI%5B%22%E9%A9%BB%E6%B3%A2%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20R%5B%22%E5%BA%95%E9%9D%A2%20r%22%5D%20--%3E%20PHI%0A%20%20TOP%5B%22%E9%A1%B6%E9%9D%A2%E5%8F%8D%E5%B0%84%22%5D%20--%3E%20COUP%0A%20%20COUP%20--%3E%20CD%5B%22CD(d)%20%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20PHI%20--%3E%20CD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="与-bossung-的正交" tabindex="-1">与 Bossung 的正交 <a class="header-anchor" href="#与-bossung-的正交" aria-label="Permalink to &quot;与 Bossung 的正交&quot;">​</a></h3><p>Bossung 扫的是焦点与剂量；swing 扫的是厚度。两者都改 CD，轴不同。最佳焦可以随 \\(d\\) 微移（有效光程），于是 swing 与焦窗耦合。本课先把 \\(d\\) 轴单独画清；选厚时再与焦深交。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学厚度 \\(n d\\) 每增加 \\(\\lambda/2\\)，往返相位 \\(4\\pi n d/\\lambda\\) 转 \\(2\\pi\\)，干涉条件循环一次。故 \\(\\Delta d\\sim\\lambda/(2n)\\)。振幅 \\(\\propto\\) 两列波的对比，即顶、底反射振幅之积一类因子。CAR 的酸扩散沿 \\(z\\) 糊驻波，可以减小侧壁波纹，但对 swing 的能量耦合项帮助有限——糊的是节点，不是净剂量。因此「PEB 更狠」不是 BARC 的替代。</p><p><span class="marginnote">数字实例：干式 193 nm 光刻，胶的折射率 \\(n\\approx1.7\\)，摆动周期就是 \\(193/(2\\times1.7)\\approx57\\) nm。也就是说胶厚只要差约 28 nm（半个周期），同一片晶圆上的 CD 就可能从波峰掉到波谷。</span></p>',5)),(n(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%83%B6%E5%8E%9A%20d%20%E5%A2%9E%E5%8A%A0%20%CE%BB%2F(4n)%22%5D%20--%3E%20B%5B%22%E5%BE%80%E8%BF%94%E7%9B%B8%E4%BD%8D%204%CF%80nd%2F%CE%BB%20%E8%BD%AC%E5%8D%8A%E4%B8%AA%E5%91%A8%E6%9C%9F%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%BA%95%E9%9D%A2%E5%8F%8D%E5%B0%84%E6%B3%A2%E7%9B%B8%E9%95%BF%E4%B8%8E%E7%9B%B8%E6%B6%88%E4%BA%92%E6%8D%A2%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%BF%9B%E8%83%B6%E5%87%80%E8%80%A6%E5%90%88%E8%83%BD%E9%87%8F%E5%8F%96%E6%9E%81%E5%80%BC%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%9B%BA%E5%AE%9A%E5%89%82%E9%87%8F%E4%B8%8B%20CD%20%E6%91%86%E5%88%B0%E5%B3%B0%E6%88%96%E8%B0%B7%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%86%8D%E5%A2%9E%20%CE%BB%2F(4n)%20%E5%9B%9E%E5%88%B0%E5%8E%9F%E5%B9%B2%E6%B6%89%E7%8A%B6%E6%80%81%22%5D%0A%20%20F%20--%3E%20A%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p><span class="marginnote">常见误区：初学者容易以为 CD 漂了就该调剂量。剂量环反馈的是曝光面能量，完全「看不见」胶厚变了多少——摆动走的是厚度轴，靠拧剂量追 CD 只会把别的尺寸项带偏，正解是减反（BARC）或选厚度工作点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不指定某胶的 \\(n\\) 到小数点后三位当唯一周期。溶剂残留、致密化让有效 \\(n\\) 和 \\(d\\) 在软烤后变，摆动要以烤后厚度计量。禁止编造未公开的 swing 纳米峰峰值当「典型值」。下一课才谈选在波峰还是波谷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摆动曲线是 CD 或 \\(E_\\mathrm{size}\\) 对胶厚的振荡，周期约 \\(\\lambda/(2n)\\)。</li><li>底面 \\(|r|\\) 与顶面反射分别贡献振幅；剂量环不锁厚度。</li><li>与 Bossung 的 \\(z\\) 轴正交，但最佳焦可随 \\(d\\) 微移。</li><li>酸扩散糊节点，不替代减反。</li><li>下一课：在曲线上选工作点。</li><li>出处：Mack；Born &amp; Wolf；Levinson。</li></ul>',5))])}const f=o(A,[["render",p]]);export{u as __pageData,f as default};
